@_ods_cext.register_operation(_Dialect)
class ConfigureLaunchOp(_ods_ir.OpView):
  r"""
  This function computes the shape of the grid, threadblock, and cluster.
  It is used by the host runtime to launch the device kernel.
  
  The op returns no values available to the device function. The body of the op
  must terminate with `lir.detail.configure_launch.return` yielding at minimum:
  
  - grid dimensions (type `!cute.shape<"(?,?,?)">`) [mandatory]
  - block dimensions (type `!cute.shape<"(?,?,?)">`) [mandatory]
  
  The return op also accepts optional cluster dimensions and dynamic shared memory;
  see `lir.detail.configure_launch.return` for details.
  
  Example MLIR (minimal):
  ```mlir
  lir.detail.configure_launch(%argProblem) : (!cute.shape<"(?,?,?,?)">) -> () {
  ^bb(%problem: !cute.shape<"(?,?,?,?)">):
  
    %c128_i32 = arith.constant 128 : i32
    %c64_i32 = arith.constant 64 : i32
  
    %grid = cute.make_shape(%c128_i32, %c128_i32, %c64_i32)  : (i32,i32,i32) -> !cute.shape<"(?,?,?)">
    %block = cute.make_shape(%c128_i32, %c128_i32, %c64_i32) : (i32,i32,i32) -> !cute.shape<"(?,?,?)">
  
    lir.detail.configure_launch.return %grid, %block
      : !cute.shape<"(?,?,?)">, !cute.shape<"(?,?,?)">
  }
  ```
  
  Example MLIR (fully explicit):
  ```mlir
  lir.detail.configure_launch(%argProblem) : (!cute.shape<"(?,?,?,?)">) -> () {
  ^bb(%problem: !cute.shape<"(?,?,?,?)">):
  
    %c1_i32 = arith.constant 1 : i32
    %c128_i32 = arith.constant 128 : i32
    %c64_i32 = arith.constant 64 : i32
  
    %grid = cute.make_shape(%c128_i32, %c128_i32, %c64_i32)  : (i32,i32,i32) -> !cute.shape<"(?,?,?)">
    %block = cute.make_shape(%c128_i32, %c128_i32, %c64_i32) : (i32,i32,i32) -> !cute.shape<"(?,?,?)">
    %preferredCluster = cute.make_shape(%c1_i32, %c1_i32, %c1_i32)    : (i32,i32,i32) -> !cute.shape<"(?,?,?)">
    %fallbackCluster  = cute.make_shape(%c1_i32, %c1_i32, %c1_i32)    : (i32,i32,i32) -> !cute.shape<"(?,?,?)">
    %dynamic_smem = arith.constant 232448 : i32
  
    lir.detail.configure_launch.return %grid, %block, cluster(%preferredCluster, %fallbackCluster), smem(%dynamic_smem)
      : !cute.shape<"(?,?,?)">, !cute.shape<"(?,?,?)">, !cute.shape<"(?,?,?)">, !cute.shape<"(?,?,?)">, i32
  }
  ```
  """

  OPERATION_NAME = "lir.detail.configure_launch"

  _ODS_REGIONS = (1, True)

  def __init__(self, inputs: _Sequence[_ods_ir.Value], *, loc: _Optional[_ods_ir.Location] = None, ip: _Optional[_ods_ir.InsertionPoint] = None):
    operands = []
    attributes = {}
    regions = None
    operands.extend(_get_op_results_or_values(inputs))
    _ods_context = _ods_get_default_loc_context(loc)
    results = []
    _ods_successors = None
    super().__init__(self.OPERATION_NAME, self._ODS_REGIONS, self._ODS_OPERAND_SEGMENTS, self._ODS_RESULT_SEGMENTS, attributes=attributes, results=results, operands=operands, successors=_ods_successors, regions=regions, loc=loc, ip=ip)

  @builtins.property
  def inputs(self) -> _ods_ir.OpOperandList:
    _ods_variadic_group_length = len(self.operation.operands) - 1 + 1
    return self.operation.operands[0:0 + _ods_variadic_group_length]

  @builtins.property
  def body(self) -> _ods_ir.Region:
    return self.regions[0]

