@_ods_cext.register_operation(_Dialect)
class ConsumerReleaseOp(_ods_ir.OpView):
  r"""
  Signals that the consumer has finished reading from the current pipeline
  stage, making it available for the producer to reuse. This is typically
  the last consumer operation in a pipeline loop iteration, paired with a
  preceding `lir.consumer_wait`.
  
  The concrete synchronization mechanism depends on the pipeline type
  (e.g. mbarrier arrival or named-barrier sync). For some pipeline
  configurations this may lower to a no-op when the final fence is
  deferred to `lir.pipeline_tail`.
  
  The result state is identical to the input state (no state transition
  occurs). It exists only for legacy SSA ordering reasons.
  
  When `elect_one_sync` is set, only a single thread performs the
  signaling operation. This lowers to `elect.sync` with a full-warp
  member mask, so it requires full warp participation: all 32 lanes of
  each executing warp must be converged and active when the op executes.
  """

