@_ods_cext.register_operation(_Dialect)
class GridInvariantOp(_ods_ir.OpView):
  r"""
  `lir.grid_invariant` wraps a region whose results are computed once per
  kernel launch (i.e. they do not vary across thread-blocks or threads).
  The region may freely capture SSA values defined in the enclosing
  `lir.func` body, including its block arguments.
  
  This op must be a direct child of `lir.func`.  It is lowered to
  `lir.detail.initialize_params` by the `lir-outline-grid-invariant` pass,
  which computes the backward slice of values entering the region and hoists
  the computation into an isolated, host-executable form.
  
  Example:
  
  ```mlir
  lir.func @kernel(%arg0: i32, %arg1: i32) {
    %scale = arith.constant 4 : i32
    %base = arith.muli %arg0, %scale : i32
  
    %0, %1 = lir.grid_invariant {
      %a = arith.addi %base, %arg1 : i32
      %b = arith.muli %arg1, %scale : i32
      lir.yield %a, %b : i32, i32
    } : i32, i32
  
    // use %0, %1 ...
  }
  ```
  """

