@_ods_cext.register_operation(_Dialect)
class PartitionOp(_ods_ir.OpView):
  r"""
  Partition the input cute.memref with the layout_tv and tiler, then slice it with the agent_id.
  
  Example:
  ```mlir
  %partitioned = lir.partition(%buffer, %agent_id)
    { layout_tv = #cute.layout<"((16,8),(8,8)):((8,128),(1,1024))">
      tiler = #cute.tile<"[128:1;64:1]">}
  : !cute.memref<f16, gmem, "(128,128):(1,1)">, i32
  ```
  
  Internally, it is equivalent to the following operations
  ```mlir
  %buffer_div = cute.zipped_divide(%buffer, %tiler)
  %thrfrg = cute.composition(%buffer_div, tile{%layout_tv,_})
  %dst = cute.slice(%thrfrg, coord((%agent_id,_),_))
  ```
  
  When `tiler` is omitted, the partition is fully captured by `layout_tv`
  alone and the `zipped_divide` stage is skipped — `layout_tv` is composed
  directly with the buffer layout. The slice coord unwraps the V mode so
  its sub-modes are exposed at the top level of the result (a rank-N tuple
  of `_` where N is the rank of layout_tv's V mode; a bare `_` when V is
  scalar):
  ```mlir
  %thrfrg = cute.composition(%buffer, %layout_tv)
  %dst = cute.slice(%thrfrg, coord(%agent_id, (_,_,...,_)))
  ```
  """

  OPERATION_NAME = "lir.partition"

  _ODS_REGIONS = (0, True)

  def __init__(self, buffer: _ods_ir.Value, agent_id: _ods_ir.Value, layout_tv: _Union[_Any, _ods_ir.Attribute], *, tiler: _Optional[_Union[_Any, _ods_ir.Attribute]] = None, results: _Optional[_Sequence[_ods_ir.Type]] = None, loc: _Optional[_ods_ir.Location] = None, ip: _Optional[_ods_ir.InsertionPoint] = None):
    operands = []
    attributes = {}
    regions = None
    operands.append(buffer)
    operands.append(agent_id)
    _ods_context = _ods_get_default_loc_context(loc)
    attributes["layout_tv"] = (layout_tv if (
    isinstance(layout_tv, _ods_ir.Attribute) or
    not _ods_ir.AttrBuilder.contains('CuteLayoutAttr')) else
      _ods_ir.AttrBuilder.get('CuteLayoutAttr')(layout_tv, context=_ods_context))
    if tiler is not None: attributes["tiler"] = (tiler if (
        isinstance(tiler, _ods_ir.Attribute) or
        not _ods_ir.AttrBuilder.contains('CuteTileAttr')) else
          _ods_ir.AttrBuilder.get('CuteTileAttr')(tiler, context=_ods_context))
    _ods_successors = None
    super().__init__(self.OPERATION_NAME, self._ODS_REGIONS, self._ODS_OPERAND_SEGMENTS, self._ODS_RESULT_SEGMENTS, attributes=attributes, results=results, operands=operands, successors=_ods_successors, regions=regions, loc=loc, ip=ip)

  @builtins.property
  def buffer(self) -> _ods_ir.Value:
    return self.operation.operands[0]

  @builtins.property
  def agent_id(self) -> _ods_ir.Value:
    return self.operation.operands[1]

  @builtins.property
  def layout_tv(self) -> _ods_ir.Attribute:
    return self.operation.attributes["layout_tv"]

  @layout_tv.setter
  def layout_tv(self, value: _ods_ir.Attribute):
    if value is None:
      raise ValueError("'None' not allowed as value for mandatory attributes")
    self.operation.attributes["layout_tv"] = value

  @builtins.property
  def tiler(self) -> _Optional[_ods_ir.Attribute]:
    if "tiler" not in self.operation.attributes:
      return None
    return self.operation.attributes["tiler"]

  @tiler.setter
  def tiler(self, value: _Optional[_ods_ir.Attribute]):
    if value is not None:
      self.operation.attributes["tiler"] = value
    elif "tiler" in self.operation.attributes:
      del self.operation.attributes["tiler"]

  @tiler.deleter
  def tiler(self):
    del self.operation.attributes["tiler"]

  @builtins.property
  def dst(self) -> _ods_ir.OpResult:
    return self.operation.results[0]

