@_ods_cext.register_operation(_Dialect)
class PredicatedTensorOriginOp(_ods_ir.OpView):
  r"""
  This operation is a semantic marker that declares the *origin* (root) of the
  coordinate system whose shape is used as `predBounds` when constructing a
  predicate tensor for predicated copies (and similarly, the origin of the
  partitioning chain used for TMA coordinate tensors).
  
  Why this exists:
  - The compiler’s backward dataflow may otherwise stop at an intermediate
    `cute.make_view` (or another “re-materialized” view) that is not the
    developer’s intended origin, leading to surprising bounds selection.
  - By explicitly marking an origin, we can remove ambiguity and also detect
    “escapes” where the compiler cannot establish a valid origin (and then
    emit a compilation error at the consuming copy op).
  
  The operation is a no-op at runtime: it returns the same view type as its
  input. It is meant purely to guide analysis and rewriting passes.
  
  Example:
  
  ```mlir
  %origin = lir.predicated_tensor_origin(%gmem) : !cute.memref<...>
  // Any partitioning/slicing chain rooted at %origin will use shape(%origin)
  // as predication bounds.
  ```
  """

  OPERATION_NAME = "lir.predicated_tensor_origin"

  _ODS_REGIONS = (0, True)

  def __init__(self, input: _ods_ir.Value, *, results: _Optional[_Sequence[_ods_ir.Type]] = None, loc: _Optional[_ods_ir.Location] = None, ip: _Optional[_ods_ir.InsertionPoint] = None):
    operands = []
    attributes = {}
    regions = None
    operands.append(input)
    _ods_context = _ods_get_default_loc_context(loc)
    if results is None: results = [operands[0].type] * 1
    _ods_successors = None
    super().__init__(self.OPERATION_NAME, self._ODS_REGIONS, self._ODS_OPERAND_SEGMENTS, self._ODS_RESULT_SEGMENTS, attributes=attributes, results=results, operands=operands, successors=_ods_successors, regions=regions, loc=loc, ip=ip)

  @builtins.property
  def input(self) -> _ods_ir.Value:
    return self.operation.operands[0]

  @builtins.property
  def result(self) -> _ods_ir.OpResult:
    return self.operation.results[0]

